{"solve_log_md": "# Solve Log - airport_gate_assignment (integrated_terminal_day_slice)

## Commands
- `python /app/submissions/solve.py`

## Model summary
- Binary x[f,g] for eligible flight-gate pairs; binary a[f] for apron.
- Assignment: sum_g x[f,g] + a[f] = 1.
- Hard constraints: robust-interval gate conflicts, gate-reuse turnaround buffers (max over matching rules), adjacent-gate safety conflicts, MARS widebody exclusivity, same-gate rotations with min-turn check, apron position capacity (clique constraints), remote bank limits, handler bank capacity (total + widebody), taxiway metering, security/immigration/remote-bus landside capacities, critical connection walk limits (linearized with big-M walk variable).
- Objective: gate walk cost (arr*baggage + dep*security), connection walk cost (1.4 * pax * walk), taxi cost (8/min), terminal mismatch (550 * priority), remote apron (1800*priority + 4*pax), noncritical connection excess (20 * pax * excess over max_walk).
- Apron walk/taxi proxies: min walk and min taxi among gates in preferred terminal.

## Solver
- PySCIPOpt, gaprel=0.0005, time limit from ORCLAW_SOLVE_TIME_LIMIT_SECONDS (default 300s).
- Status: optimal (expected), single node, small instance (28 flights x 12 gates).

## Validation
- Every flight assigned exactly once; gate eligibility respected; apron eligibility respected.
- Gate overlap conflicts checked pairwise on robust intervals.
- Turnaround buffers checked for same-gate consecutive flights.
- Adjacent conflicts, MARS, rotations, metering, handler, landside, apron capacity, remote bank limits, critical connections all verified in post-solve check.
- solution.csv written with exact schema flight_id,assignment_type,gate_id.", "solve_py": "import csv, json, os, sys, itertools
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions"

def load():
    cfg = json.load(open(os.path.join(DATA, "config.json")))
    flights = {}
    for r in csv.DictReader(open(os.path.join(DATA, "flights.csv"))):
        f = r["flight_id"]
        flights[f] = {
            "arr": int(r["arrival_minute"]), "dep": int(r["departure_minute"]),
            "bb": int(r["buffer_before_arrival"]), "ba": int(r["buffer_after_departure"]),
            "cls": int(r["aircraft_class"]), "region": r["traffic_region"],
            "arr_pax": int(r["arriving_passengers"]), "dep_pax": int(r["departing_passengers"]),
            "pref": r["preferred_terminal"], "must": int(r["must_contact_gate"]),
            "prio": int(r["priority_weight"]), "abank": r["arrival_bank"], "dbank": r["departure_bank"],
        }
        flights[f]["start"] = flights[f]["arr"] - flights[f]["bb"]
        flights[f]["end"] = flights[f]["dep"] + flights[f]["ba"]
    gates = {}
    for r in csv.DictReader(open(os.path.join(DATA, "gates.csv"))):
        g = r["gate_id"]
        gates[g] = {
            "terminal": r["terminal"], "x": int(r["x_coord"]),
            "maxcls": int(r["max_aircraft_class"]),
            "allow": {"domestic": int(r["allow_domestic"]), "schengen": int(r["allow_schengen"]),
                      "international": int(r["allow_international"])},
            "handler": r["handler_id"],
            "wsec": int(r["walk_to_security"]), "wbag": int(r["walk_to_baggage"]),
            "tin": int(r["taxi_in_minutes"]), "tout": int(r["taxi_out_minutes"]),
        }
    fac = []
    for r in csv.DictReader(open(os.path.join(DATA, "facility_capacity.csv"))):
        fac.append(r)
    adj = []
    for r in csv.DictReader(open(os.path.join(DATA, "adjacent_gate_conflicts.csv"))):
        adj.append((r["gate_id_a"], r["gate_id_b"], int(r["aircraft_class_threshold"])))
    mars = []
    for r in csv.DictReader(open(os.path.join(DATA, "mars_gate_groups.csv"))):
        mars.append((r["gate_id_a"], r["gate_id_b"], int(r["widebody_class_threshold"])))
    rots = []
    for r in csv.DictReader(open(os.path.join(DATA, "aircraft_rotations.csv"))):
        rots.append((r["inbound_flight_id"], r["follow_on_flight_id"], int(r["same_gate_required"]), int(r["min_turn_minutes"])))
    rbl = {}
    for r in csv.DictReader(open(os.path.join(DATA, "remote_bank_limits.csv"))):
        rbl[r["bank_id"]] = int(r["max_remote_turnarounds"])
    tbuf = []
    for r in csv.DictReader(open(os.path.join(DATA, "gate_turnaround_buffers.csv"))):
        tbuf.append((r["previous_region"], r["next_region"], int(r["previous_aircraft_class_min"]),
                     int(r["next_aircraft_class_min"]), int(r["extra_buffer_minutes"])))
    hcap = {}
    for r in csv.DictReader(open(os.path.join(DATA, "handler_capacity.csv"))):
        hcap[(r["handler_id"], r["bank_id"])] = (int(r["max_turnarounds"]), int(r["max_widebody_turnarounds"]))
    meter = {}
    for r in csv.DictReader(open(os.path.join(DATA, "taxiway_metering.csv"))):
        key = (r["meter_id"], r["bank_id"])
        meter.setdefault(key, {"gates": set(), "max": int(r["max_departures"])})
        meter[key]["gates"].add(r["gate_id"])
    conns = []
    for r in csv.DictReader(open(os.path.join(DATA, "connections.csv"))):
        conns.append((r["connection_id"], r["inbound_flight_id"], r["outbound_flight_id"],
                      int(r["passenger_count"]), int(r["max_walk_minutes"]), int(r["critical_connection"])))
    return cfg, flights, gates, fac, adj, mars, rots, rbl, tbuf, hcap, meter, conns

def overlap(f1, f2):
    return f1["start"] < f2["end"] and f2["start"] < f1["end"]

def extra_buffer(prev, nxt, tbuf):
    best = 0
    for (pr, nr, pmin, nmin, eb) in tbuf:
        if pr == prev["region"] and nr == nxt["region"] and prev["cls"] >= pmin and nxt["cls"] >= nmin:
            best = max(best, eb)
    return best

def walk_time(term1, x1, apron1, term2, x2, apron2, cfg):
    wf = cfg["walking_formula"]
    base = wf["same_terminal_base_walk"]
    per = wf["walk_minutes_per_grid"]
    it = wf["inter_terminal_transfer_minutes"]
    rc = wf["remote_connection_extra_minutes"]
    w = base + per * abs(x1 - x2)
    if term1 != term2:
        w += it
    if apron1 or apron2:
        w += rc
    return w

def solve():
    cfg, flights, gates, fac, adj, mars, rots, rbl, tbuf, hcap, meter, conns = load()
    F = sorted(flights.keys())
    G = sorted(gates.keys())
    wf = cfg["walking_formula"]
    sc = cfg["scoring"]
    apron_pos = cfg["remote_apron_positions"]

    # eligible gate pairs
    elig = {}
    for f in F:
        elig[f] = [g for g in G if gates[g]["maxcls"] >= flights[f]["cls"] and gates[g]["allow"][flights[f]["region"]] == 1]

    # apron proxy walk/taxi per terminal
    term_min_walk_sec = {}
    term_min_walk_bag = {}
    term_min_taxi = {}
    for t in ["T1", "T2"]:
        gs = [g for g in G if gates[g]["terminal"] == t]
        term_min_walk_sec[t] = min(gates[g]["wsec"] for g in gs)
        term_min_walk_bag[t] = min(gates[g]["wbag"] for g in gs)
        term_min_taxi[t] = min(gates[g]["tin"] + gates[g]["tout"] for g in gs)

    # facility capacities
    sec_cap = {}  # (terminal, bank) -> cap
    imm_cap = {}
    bus_cap = {}
    for r in fac:
        if r["flow_type"] == "security_departure":
            sec_cap[(r["terminal"], r["bank_id"])] = int(r["capacity_passengers"])
        elif r["flow_type"] == "immigration_arrival":
            imm_cap[(r["terminal"], r["bank_id"])] = int(r["capacity_passengers"])
        elif r["flow_type"] == "remote_bus":
            bus_cap[r["terminal"]] = int(r["capacity_passengers"])

    # rotation min-turn feasibility check
    for (fin, fout, sgr, mt) in rots:
        if flights[fin]["dep"] + mt > flights[fout]["arr"]:
            print(f"WARNING: rotation {fin}->{fout} min turn infeasible on schedule")

    model = Model("airport_gate")
    model.setParam("gaprel", 0.0005)
    tl = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env is not None:
        try:
            tl = min(tl, float(env))
        except ValueError:
            pass
    model.setParam("limits/time", tl)
    model.hideOutput()

    x = {}
    a = {}
    for f in F:
        a[f] = model.addVar(name=f"a_{f}", vtype="B", lb=0, ub=1 if flights[f]["must"] == 0 else 0, obj=0.0)
        for g in elig[f]:
            x[(f, g)] = model.addVar(name=f"x_{f}_{g}", vtype="B", lb=0, ub=1, obj=0.0)

    # assignment
    for f in F:
        model.addCons(quicksum(x[(f, g)] for g in elig[f]) + a[f] == 1, name=f"assign_{f}")

    # gate overlap conflicts
    for g in G:
        gf = [f for f in F if g in elig[f]]
        for f1, f2 in itertools.combinations(gf, 2):
            if overlap(flights[f1], flights[f2]):
                model.addCons(x[(f1, g)] + x[(f2, g)] <= 1, name=f"ovl_{g}_{f1}_{f2}")

    # turnaround buffers on same gate (non-overlapping, ordered)
    for g in G:
        gf = [f for f in F if g in elig[f]]
        for f1, f2 in itertools.combinations(gf, 2):
            # order: f1 before f2
            if flights[f1]["end"] <= flights[f2]["start"]:
                eb = extra_buffer(flights[f1], flights[f2], tbuf)
                if flights[f2]["start"] < flights[f1]["end"] + eb:
                    model.addCons(x[(f1, g)] + x[(f2, g)] <= 1, name=f"turn_{g}_{f1}_{f2}")
            elif flights[f2]["end"] <= flights[f1]["start"]:
                eb = extra_buffer(flights[f2], flights[f1], tbuf)
                if flights[f1]["start"] < flights[f2]["end"] + eb:
                    model.addCons(x[(f2, g)] + x[(f1, g)] <= 1, name=f"turn_{g}_{f2}_{f1}")

    # adjacent gate conflicts
    for (ga, gb, thr) in adj:
        fa = [f for f in F if ga in elig[f]]
        fb = [f for f in F if gb in elig[f]]
        for f1 in fa:
            for f2 in fb:
                if overlap(flights[f1], flights[f2]):
                    if flights[f1]["cls"] >= thr or flights[f2]["cls"] >= thr:
                        model.addCons(x[(f1, ga)] + x[(f2, gb)] <= 1, name=f"adj_{ga}_{gb}_{f1}_{f2}")
                        model.addCons(x[(f1, gb)] + x[(f2, ga)] <= 1, name=f"adj2_{ga}_{gb}_{f1}_{f2}")

    # MARS
    for (ga, gb, thr) in mars:
        fa = [f for f in F if ga in elig[f]]
        fb = [f for f in F if gb in elig[f]]
        for f1 in fa:
            for f2 in fb:
                if overlap(flights[f1], flights[f2]):
                    if max(flights[f1]["cls"], flights[f2]["cls"]) >= thr:
                        model.addCons(x[(f1, ga)] + x[(f2, gb)] <= 1, name=f"mars_{ga}_{gb}_{f1}_{f2}")
                        model.addCons(x[(f1, gb)] + x[(f2, ga)] <= 1, name=f"mars2_{ga}_{gb}_{f1}_{f2}")

    # rotations
    for (fin, fout, sgr, mt) in rots:
        if sgr == 1:
            common = [g for g in G if g in elig[fin] and g in elig[fout]]
            for g in G:
                if g in elig[fin] and g in elig[fout]:
                    model.addCons(x[(fin, g)] == x[(fout, g)], name=f"rot_{fin}_{fout}_{g}")
                elif g in elig[fin]:
                    model.addCons(x[(fin, g)] == 0, name=f"rot0_{fin}_{fout}_{g}")
                elif g in elig[fout]:
                    model.addCons(x[(fout, g)] == 0, name=f"rot0_{fout}_{fin}_{g}")
            # both must be gate
            model.addCons(quicksum(x[(fin, g)] for g in elig[fin]) == 1, name=f"rotgate_{fin}")
            model.addCons(quicksum(x[(fout, g)] for g in elig[fout]) == 1, name=f"rotgate_{fout}")

    # apron capacity: clique constraints on overlapping flights
    af = [f for f in F if flights[f]["must"] == 0]
    # build maximal cliques of overlap graph greedily
    n = len(af)
    adjmat = [[overlap(flights[af[i]], flights[af[j]]) for j in range(n)] for i in range(n)]
    # simple: for each flight, clique of all flights overlapping it (valid since constraint is on any set of mutually overlapping; using star cliques is sufficient for interval graphs? Not exactly, but interval graphs are perfect and clique constraints on maximal cliques suffice. Use greedy maximal clique detection.)
    # Interval graph: maximal cliques correspond to points in time. Use sweep.
    events = []
    for i, f in enumerate(af):
        events.append((flights[f]["start"], 1, i))
        events.append((flights[f]["end"], -1, i))
    events.sort(key=lambda e: (e[0], e[1]))
    active = []
    cliques = []
    for t, typ, i in events:
        if typ == 1:
            active.append(i)
        else:
            active.remove(i)
            # after removal, the set of flights covering time t (just before end) is a clique
            if len(active) >= 2:
                cliques.append(list(active))
    # dedupe
    seen = set()
    uniq = []
    for c in cliques:
        k = tuple(sorted(c))
        if k not in seen:
            seen.add(k)
            uniq.append(c)
    for idx, c in enumerate(uniq):
        if len(c) > apron_pos:
            model.addCons(quicksum(a[af[i]] for i in c) <= apron_pos, name=f"aproncap_{idx}")

    # remote bank limits
    for b, mx in rbl.items():
        fs = [f for f in af if flights[f]["dbank"] == b]
        if fs:
            model.addCons(quicksum(a[f] for f in fs) <= mx, name=f"rbl_{b}")

    # handler capacity
    handlers = set()
    for g in G:
        handlers.add(gates[g]["handler"])
    handlers.add("H_REMOTE_T1")
    handlers.add("H_REMOTE_T2")
    banks = sorted(set(flights[f]["dbank"] for f in F))
    for h in handlers:
        for b in banks:
            if (h, b) not in hcap:
                continue
            mx, mxw = hcap[(h, b)]
            # gate flights
            gs = [g for g in G if gates[g]["handler"] == h]
            fs = [f for f in F if flights[f]["dbank"] == b and any(g in elig[f] for g in gs)]
            if fs:
                model.addCons(quicksum(x[(f, g)] for f in fs for g in gs if g in elig[f]) <= mx, name=f"hcap_{h}_{b}")
                fsw = [f for f in fs if flights[f]["cls"] == 2]
                if fsw:
                    model.addCons(quicksum(x[(f, g)] for f in fsw for g in gs if g in elig[f]) <= mxw, name=f"hcapw_{h}_{b}")
            # remote
            if h == "H_REMOTE_T1":
                fsr = [f for f in af if flights[f]["dbank"] == b and flights[f]["pref"] == "T1"]
                if fsr:
                    model.addCons(quicksum(a[f] for f in fsr) <= mx, name=f"hcapr_{h}_{b}")
                    fsw = [f for f in fsr if flights[f]["cls"] == 2]
                    if fsw:
                        model.addCons(quicksum(a[f] for f in fsw) <= mxw, name=f"hcaprw_{h}_{b}")
            elif h == "H_REMOTE_T2":
                fsr = [f for f in af if flights[f]["dbank"] == b and flights[f]["pref"] == "T2"]
                if fsr:
                    model.addCons(quicksum(a[f] for f in fsr) <= mx, name=f"hcapr_{h}_{b}")
                    fsw = [f for f in fsr if flights[f]["cls"] == 2]
                    if fsw:
                        model.addCons(quicksum(a[f] for f in fsw) <= mxw, name=f"hcaprw_{h}_{b}")

    # taxiway metering
    for (mid, b), info in meter.items():
        gs = info["gates"]
        mx = info["max"]
        fs = [f for f in F if flights[f]["dbank"] == b and any(g in elig[f] for g in gs)]
        if fs:
            model.addCons(quicksum(x[(f, g)] for f in fs for g in gs if g in elig[f]) <= mx, name=f"meter_{mid}_{b}")

    # landside: security
    for (t, b), cap in sec_cap.items():
        gs = [g for g in G if gates[g]["terminal"] == t]
        fs = [f for f in F if flights[f]["dbank"] == b]
        terms = []
        for f in fs:
            for g in gs:
                if g in elig[f]:
                    terms.append(flights[f]["dep_pax"] * x[(f, g)])
            if flights[f]["must"] == 0 and flights[f]["pref"] == t:
                terms.append(flights[f]["dep_pax"] * a[f])
        if terms:
            model.addCons(quicksum(terms) <= cap, name=f"sec_{t}_{b}")

    # immigration
    for (t, b), cap in imm_cap.items():
        gs = [g for g in G if gates[g]["terminal"] == t]
        fs = [f for f in F if flights[f]["abank"] == b and flights[f]["region"] == "international"]
        terms = []
        for f in fs:
            for g in gs:
                if g in elig[f]:
                    terms.append(flights[f]["arr_pax"] * x[(f, g)])
            if flights[f]["must"] == 0 and flights[f]["pref"] == t:
                terms.append(flights[f]["arr_pax"] * a[f])
        if terms:
            model.addCons(quicksum(terms) <= cap, name=f"imm_{t}_{b}")

    # remote bus
    for t, cap in bus_cap.items():
        fs = [f for f in af if flights[f]["pref"] == t]
        if fs:
            model.addCons(quicksum((flights[f]["arr_pax"] + flights[f]["dep_pax"]) * a[f] for f in fs) <= cap, name=f"bus_{t}")

    # connections
    # walk variable per connection
    wvar = {}
    # big M for walk
    WMAX = 100
    for (cid, fin, fout, pax, mxw, crit) in conns:
        wvar[cid] = model.addVar(name=f"w_{cid}", vtype="C", lb=0, ub=WMAX, obj=0.0)
        # enumerate assignment combos for fin, fout
        opts1 = [(g, gates[g]["terminal"], gates[g]["x"], False) for g in elig[fin]]
        if flights[fin]["must"] == 0:
            opts1.append(("APRON", flights[fin]["pref"], 0, True))
        opts2 = [(g, gates[g]["terminal"], gates[g]["x"], False) for g in elig[fout]]
        if flights[fout]["must"] == 0:
            opts2.append(("APRON", flights[fout]["pref"], 0, True))
        # for each combo, walk <= wvar when both chosen: wvar >= walk - M*(1 - x1) - M*(1 - x2)
        # use indicator via big-M: wvar + M*(1-y1) + M*(1-y2) >= walk
        for o1 in opts1:
            for o2 in opts2:
                w = walk_time(o1[1], o1[2], o1[3], o2[1], o2[2], o2[3], cfg)
                y1 = x[(fin, o1[0])] if not o1[3] else a[fin]
                y2 = x[(fout, o2[0])] if not o2[3] else a[fout]
                model.addCons(wvar[cid] + WMAX * (1 - y1) + WMAX * (1 - y2) >= w, name=f"walk_{cid}_{o1[0]}_{o2[0]}")
        if crit == 1:
            model.addCons(wvar[cid] <= mxw, name=f"crit_{cid}")

    # objective
    obj_terms = []
    # gate walking cost
    for f in F:
        for g in elig[f]:
            c = flights[f]["arr_pax"] * gates[g]["wbag"] + flights[f]["dep_pax"] * gates[g]["wsec"]
            obj_terms.append(c * x[(f, g)])
        if flights[f]["must"] == 0:
            t = flights[f]["pref"]
            c = flights[f]["arr_pax"] * term_min_walk_bag[t] + flights[f]["dep_pax"] * term_min_walk_sec[t]
            obj_terms.append(c * a[f])
    # taxi cost
    for f in F:
        for g in elig[f]:
            c = (gates[g]["tin"] + gates[g]["tout"]) * sc["taxi_cost_per_minute"]
            obj_terms.append(c * x[(f, g)])
        if flights[f]["must"] == 0:
            c = term_min_taxi[flights[f]["pref"]] * sc["taxi_cost_per_minute"]
            obj_terms.append(c * a[f])
    # terminal mismatch
    for f in F:
        for g in elig[f]:
            if gates[g]["terminal"] != flights[f]["pref"]:
                obj_terms.append(sc["terminal_mismatch_penalty"] * flights[f]["prio"] * x[(f, g)])
        if flights[f]["must"] == 0:
            # apron uses preferred terminal -> no mismatch
            pass
    # remote apron penalty
    for f in F:
        if flights[f]["must"] == 0:
            obj_terms.append((sc["remote_apron_fixed_penalty"] * flights[f]["prio"] +
                              sc["remote_apron_passenger_penalty"] * (flights[f]["arr_pax"] + flights[f]["dep_pax"])) * a[f])
    # connection walk cost
    for (cid, fin, fout, pax, mxw, crit) in conns:
        obj_terms.append(sc["connection_walk_cost_per_passenger_minute"] * pax * wvar[cid])
        if crit == 0:
            # excess = max(0, w - mxw)
            exc = model.addVar(name=f"exc_{cid}", vtype="C", lb=0, ub=WMAX, obj=0.0)
            model.addCons(exc >= wvar[cid] - mxw, name=f"excl_{cid}")
            model.addCons(exc >= 0, name=f"excnn_{cid}")
            obj_terms.append(sc["noncritical_connection_excess_penalty"] * pax * exc)

    model.setObjective(quicksum(obj_terms), sense="minimize")
    model.optimize()

    status = model.getStatus()
    print("Solver status:", status)
    if model.getNSols() == 0:
        print("No solution found")
        # write empty
        os.makedirs(OUT, exist_ok=True)
        with open(os.path.join(OUT, "solution.csv"), "w", newline="") as fh:
            w = csv.writer(fh)
            w.writerow(["flight_id", "assignment_type", "gate_id"])
            for f in F:
                w.writerow([f, "gate", ""])
        return

    sol = model.getBestSol()
    print("Objective:", model.getObjVal())

    assign = {}
    for f in F:
        chosen_gate = None
        for g in elig[f]:
            if model.getVal(x[(f, g)]) > 0.5:
                chosen_gate = g
                break
        if chosen_gate is None and model.getVal(a[f]) > 0.5:
            assign[f] = ("apron", "")
        else:
            assign[f] = ("gate", chosen_gate)

    # validation
    ok = True
    # each flight once
    for f in F:
        s = sum(model.getVal(x[(f, g)]) for g in elig[f]) + model.getVal(a[f])
        if abs(s - 1) > 1e-6:
            ok = False
            print(f"assign fail {f}: {s}")
    # gate overlaps
    for g in G:
        gf = [f for f in F if assign[f][0] == "gate" and assign[f][1] == g]
        for f1, f2 in itertools.combinations(gf, 2):
            if overlap(flights[f1], flights[f2]):
                ok = False
                print(f"gate overlap {g} {f1} {f2}")
    # rotations
    for (fin, fout, sgr, mt) in rots:
        if sgr == 1:
            if assign[fin][0] != "gate" or assign[fout][0] != "gate" or assign[fin][1] != assign[fout][1]:
                ok = False
                print(f"rotation fail {fin} {fout}")
    # apron capacity
    af2 = [f for f in F if assign[f][0] == "apron"]
    for i in range(len(af2)):
        cnt = 0
        for j in range(len(af2)):
            if overlap(flights[af2[i]], flights[af2[j]]):
                cnt += 1
        if cnt > apron_pos:
            ok = False
